create table color (id integer generated by default as identity, hex varchar(7), code varchar(20) not null, name varchar(50) not null unique, primary key (id));
create table image (height integer, width integer, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, size_bytes bigint not null, updated_at timestamp(6) with time zone not null, checksum varchar(64) unique, content_type varchar(100) not null, alt_text varchar(500), storage_key varchar(500) not null unique, original_filename varchar(255), primary key (id));
create table product (base_price numeric(10,2), id integer generated by default as identity, description TEXT, gender varchar(255) check ((gender in ('MAN','WOMAN','UNISEX'))), name varchar(255) unique, season varchar(255) check ((season in ('SUMMER','WINTER','DEMI_SEASON','ALL_SEASON'))), primary key (id));
create table product_image (is_main boolean default false not null, product_id integer not null, sort_order integer default 0 not null, id bigint generated by default as identity, image_id bigint not null, alt_text varchar(500), primary key (id), constraint uk_product_image unique (product_id, image_id));
create table product_textile (id integer generated by default as identity, percentage integer, primary_fabric boolean, product_id integer not null, textile_id integer not null, primary key (id), constraint uk_product_textile unique (product_id, textile_id));
create table product_variant (color_id integer, id integer generated by default as identity, price numeric(10,2), product_id integer not null, size_id integer, stock_quantity integer not null, barcode varchar(50), sku varchar(50) not null unique, primary key (id), constraint uk_product_variant_product_color_size unique (product_id, color_id, size_id));
create table product_variant_image (is_main boolean not null, sort_order integer not null, variant_id integer not null, id bigint generated by default as identity, image_id bigint not null, alt_text varchar(500), primary key (id), constraint uk_product_variant_image unique (variant_id, image_id));
create table size (id integer generated by default as identity, sort_order integer not null, code varchar(20) not null, system varchar(20) not null check ((system in ('LETTER','EU','US','UK','KIDS','SHOES'))), label varchar(100), primary key (id));
create table textile (active boolean not null, density_gsm integer, id integer generated by default as identity, price_modifier numeric(10,2), manufacturer varchar(20) check ((manufacturer in ('RUSSIA','CHINA','TURKEY','BELARUS'))), stretch varchar(20) check ((stretch in ('NONE','LOW','MEDIUM','HIGH'))), weave_type varchar(30) check ((weave_type in ('WOVEN','KNITTED','NON_WOVEN','LACE','FELT'))), name varchar(100) not null unique, care_instructions varchar(500), description varchar(1000), composition varchar(255), primary key (id));
create table users (created_at timestamp(6) with time zone not null, id bigint generated by default as identity, updated_at timestamp(6) with time zone, phone varchar(20), role varchar(20) not null check ((role in ('USER','ADMIN'))), first_name varchar(50), last_name varchar(50), email varchar(100) not null unique, password varchar(255) not null, primary key (id));
